// EMULATOR-ONLY pose trace. Stock image. NVRAM off. No overlay.
// The only behaviour change is the accelerometer register-read stand-in below,
// plus skips of the unmodelled pin setup and the bus open/write/close that
// have no peripheral model. The probe, the sample completion, the copy, the
// correction, and PER_ROTATE stay native.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/trace_pose_s4.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/trace_pose_s4.mjs om-emu\n');
  process.exit(2);
}
process.env.OM_EMU_MODEL = 'E147';
process.env.OM_EMU_NVRAM = 'off';
const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
const IMAGE_BASE = 0x60021020;
const dis = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;

const ACC_INIT = 0x6006a436;
const ROTATE_INIT = 0x60077d18;
const DEVICE_CALL = 0x6006a43d;
const OPEN = 0x6006f1bf;
const ASYNC_READ = 0x6006f28e;
const CLOSE = 0x6006f39a;
const SYNC_READ = 0x6006f3a5;
const SYNC_WRITE = 0x6006f3bb;
const ISSUE = 0x6006a8ab;
const COMPLETION = 0x6006a8ca;
const PROBE = 0x6006a791;
const ACC_MAIN = 0x6006a660;
const ROTATE_TASK = 0x60077e0a;
const EXIF_GET = 0x60077de1;
const RAW = 0xa32c5690;
const INDEX = 0xa32c568c;
const FLAG = 0xa32c5688;
const ENABLE = 0x6298d7b0;
const STATE = 0x6298e3f4;
const BUF = 0x6298d7c0;
const UNPACKED = 0x6298d7ce;
const CACHE = 0x6298d758;
const G = 16384;
const OUT = resolve('work/out/trace-pose-s4.jsonl');
let DEADLINE = Date.now() + 12 * 60 * 1000;

const { loadNand, loadImage, loadBlock, createHash: fwHash } = await use('checks/lib/env.mjs');
const { Player } = await use('src/lab/player.mjs');
const { apply_uiin_layout } = await use('src/lab/play.mjs');
const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');

const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}
const seeds = [
  resolve(checkout, 'emu/checks/lib/env.mjs'),
  resolve(checkout, 'emu/src/lab/player.mjs'),
  resolve(checkout, 'emu/src/lab/play.mjs'),
  resolve(checkout, 'emu/scenarios/session_replay.mjs'),
  fileURLToPath(import.meta.url),
];
const seen = new Map();
const queue = [...seeds];
while (queue.length) {
  const file = queue.pop();
  if (!file || seen.has(file) || !existsSync(file)) continue;
  const data = readFileSync(file);
  seen.set(file, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
  const text = data.toString('utf8');
  IMPORT_RE.lastIndex = 0;
  let match;
  while ((match = IMPORT_RE.exec(text))) {
    const next = resolveSpec(file, match[1]);
    if (next) queue.push(next);
  }
}
const imports = [...seen.entries()]
  .map(([path, meta]) => ({ path: path.replaceAll('\\', '/'), sha256: meta.sha256, bytes: meta.bytes }))
  .sort((a, b) => a.path.localeCompare(b.path));
writeFileSync(resolve('work/out/trace-pose-s4-imports.json'), JSON.stringify(imports, null, 2) + '\n');

const lines = [];
const log = (row) => {
  row.t = Date.now();
  lines.push(JSON.stringify(row));
  writeFileSync(OUT, lines.join('\n') + '\n');
  console.log(JSON.stringify({ step: row.step, error: row.error || null, raw: row.raw, index: row.index, exif: row.exif }));
};
const msg = (e) => String(e && e.stack ? e.stack : e).slice(0, 800);

const fw = { rom: loadImage(), resBlock: loadBlock(), summary: null, changed: [] };
apply_uiin_layout(fw.rom);
const pl = new Player(
  { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
  {
    ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
    machine: { coverage: { mark() {}, stub() {} } }, patch: fw.summary, patchRanges: fw.changed, loaded: 'on',
  },
);
pl.camapp_components = true;
pl.camapp_native_tra = true;

let sample = new Uint8Array(14);
const counts = {};
const bump = (name) => { counts[name] = (counts[name] || 0) + 1; };
const first = {};

let failed = null;
try {
  log({ step: 'open' });
  pl.open_session();
  DEADLINE = Date.now() + 8 * 60 * 1000;
  const s = pl.session;
  const l = s.lab;
  const sim = l.sim;
  const u16 = (a) => { const b = sim.read(a, 2); return b[0] | (b[1] << 8); };
  const i16 = (a) => { const v = u16(a); return v & 0x8000 ? v - 0x10000 : v; };
  const idle = (ms) => {
    const to = l.lab_time() + ms * 1e6;
    while (l.lab_time() < to && Date.now() < DEADLINE) s.idle_slice(Math.min(to, l.lab_time() + 50e6));
  };
  const note = (name) => (lab, r) => {
    bump(name);
    if (!first[name]) first[name] = { from: r.mdr >>> 0, n: counts[name] };
  };
  l.observe(dis(PROBE), note('probe'), 'obs-acc-probe');
  l.observe(dis(ACC_MAIN), note('acc-main'), 'obs-acc-main');
  l.observe(dis(COMPLETION), note('completion'), 'obs-acc-completion');
  l.observe(dis(ROTATE_TASK), note('rotate-task'), 'obs-per-rotate');
  l.observe(dis(EXIF_GET), note('exif-get'), 'obs-exif-get');

  l.hook(dis(DEVICE_CALL), (h, r) => { bump('skip-device'); h.skip_call(r); }, 'EMULATOR-ONLY acc pin setup skipped');
  l.hook(dis(OPEN), (h, r) => { bump('open'); h.finish(r, { d0: 0 }); }, 'EMULATOR-ONLY acc bus open');
  l.hook(dis(CLOSE), (h, r) => { bump('close'); h.finish(r, { d0: 0 }); }, 'EMULATOR-ONLY acc bus close');
  l.hook(dis(SYNC_WRITE), (h, r) => { bump('write'); h.finish(r, { d0: 0 }); }, 'EMULATOR-ONLY acc register write');
  l.hook(dis(SYNC_READ), (h, r) => {
    bump('sync-read');
    const reg = r.d1 & 0xff;
    const n = Math.min(r.a1 >>> 0, 16);
    const bytes = new Uint8Array(n);
    if (reg === 0x0f && n >= 1) bytes[0] = 0x70;
    if (n) sim.write(r.a0 >>> 0, bytes);
    if (counts['sync-read'] <= 6) log({ step: 'sync-read', reg, n, from: r.mdr >>> 0 });
    h.finish(r, { d0: 0 });
  }, 'EMULATOR-ONLY acc sync register read');
  l.hook(dis(ASYNC_READ), (h, r) => {
    bump('async-read');
    const reg = r.d1 & 0xff;
    if (reg === 0x20) sim.write(r.a0 >>> 0, sample);
    else sim.write(r.a0 >>> 0, new Uint8Array(14));
    if (counts['async-read'] <= 8) log({ step: 'async-read', reg, buf: r.a0 >>> 0, from: r.mdr >>> 0 });
    h.finish(r, { d0: 0 });
  }, 'EMULATOR-ONLY acc sample register read');

  for (const entry of [ACC_MAIN, 0x6006a720, ROTATE_TASK, 0x6007d7bb]) l.lt.allow.add(dis(entry));

  const call = (name, fn, frame, regs = null, limit = 1000000) => {
    try {
      const r = l.call(dis(fn), regs, null, frame, limit);
      log({ step: name, ok: true, d0: r.d0 >>> 0, pc: r.pc >>> 0 });
      return r;
    } catch (e) {
      log({ step: name, ok: false, error: msg(e) });
      return null;
    }
  };

  call('acc-init', ACC_INIT, null);
  call('rotate-init', ROTATE_INIT, null);
  idle(300);
  const snap = (step) => {
    let exif = null;
    try { exif = l.call(dis(EXIF_GET), null, null, null, 200000).d0 & 0xffff; } catch (e) { exif = 'err:' + msg(e).slice(0, 200); }
    const row = {
      step, raw: u16(RAW), index: sim.u32(INDEX) >>> 0, flag: sim.u32(FLAG) >>> 0,
      enable: u16(ENABLE), state: sim.u32(STATE) >>> 0, exif,
      unpacked: [i16(UNPACKED), i16(UNPACKED + 2), i16(UNPACKED + 4)],
      cache: [i16(CACHE), i16(CACHE + 2), i16(CACHE + 4)],
      buf: [...sim.read(BUF, 14)],
      counts: { ...counts }, first,
    };
    log(row);
    return row;
  };
  snap('after-init');

  const poses = [
    ['x+', G, 0, 0], ['x-', -G, 0, 0],
    ['y+', 0, G, 0], ['y-', 0, -G, 0],
    ['z+', 0, 0, G], ['z-', 0, 0, -G],
  ];
  for (const [name, x, y, z] of poses) {
    if (Date.now() > DEADLINE) { log({ step: 'deadline', name }); break; }
    const b = new Uint8Array(14);
    const put = (off, v) => { const n = v < 0 ? v + 65536 : v; b[off] = n & 0xff; b[off + 1] = (n >> 8) & 0xff; };
    put(8, x); put(10, y); put(12, z);
    sample = b;
    const before = counts['async-read'] || 0;
    call('issue-' + name, ISSUE, [0, 0]);
    call('completion-' + name, COMPLETION, [0, 0]);
    idle(400);
    const row = snap('pose-' + name);
    row.sample = [x, y, z];
    row.readFired = (counts['async-read'] || 0) > before;
    log({ step: 'pose-note-' + name, readFired: row.readFired, sample: [x, y, z] });
  }
  log({ step: 'done', counts });
} catch (e) {
  failed = e;
  log({ step: 'fail', error: msg(e) });
} finally {
  try { pl.close(); } catch { /* session already closed */ }
}
if (failed) process.exitCode = 1;
